```cpp
#include <array>
#include <vector>
#include <cstddef>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    const int maxThreads = omp_get_max_threads();
    std::vector<std::array<size_t, 256>> local(static_cast<size_t>(maxThreads));
    for (int t = 0; t < maxThreads; ++t) local[t].fill(0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &hist = local[tid];

        #pragma omp for
        for (std::size_t i = 0; i < image.size(); ++i) {
            const int v = image[i];
            if (static_cast<unsigned>(v) < 256u) {
                hist[static_cast<std::size_t>(v)]++;
            }
            // If values are guaranteed 0..255, the check is harmless;
            // otherwise it prevents out-of-bounds.
        }
    }

    for (int t = 0; t < maxThreads; ++t) {
        for (std::size_t b = 0; b < 256; ++b) {
            bins[b] += local[t][b];
        }
    }
}
